{"row_key": "S6_01_INVARIANTS:C2.1", "source_compendium_paper": "I", "source_compendium_label": "inv:C2.1", "source_file": "fragments/part_C.tex, Statement C2.1", "source_line": 4257, "source_section": "Fr\"olicher, Bott--Chern, Aeppli, and Hermitian metrics", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[Bott--Chern and Aeppli tables as functions of $h$]\label{inv:C2.1}\label{wb:thm:exact-bott-chern-aeppli}
With
\[
H^{p,q}_{BC}=
\frac{\ker\partial\cap\ker\bar\partial\subset A^{p,q}}
{\im\partial\bar\partial},\qquad
H^{p,q}_{A}=
\frac{\ker\partial\bar\partial\subset A^{p,q}}
{\im\partial+\im\bar\partial},
\]
the complete tables are
\begin{equation}\label{inv:eq:C-BC-A}
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&1&1\\
2&0&h&2h&1\\
1&0&2&h&0\\
0&1&0&0&0
\end{array}_{BC}
\qquad
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&0&1\\
2&0&h&2&0\\
1&1&2h&h&0\\
0&1&1&0&0.
\end{array}_{A}
\end{equation}
In particular, substitution of the value $h=1$ proved in \ref{inv:A3.1} gives
the workbench's numerical tables.  The totals are
$(1,0,2,2,2,2,1)$ and $(1,2,2,2,2,0,1)$, respectively.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "citation_key": "AC2026", "original_source": "sources/original/AC26_original_manuscript.pdf", "source_sha256": "283bba102dd1d5dc346af81b28145bdaaea6654398d5032e76e97bafb9a858f2", "actual_reading_scope": "Attached original PDF: Remark 1.3 p.5; Proposition 7.27 pp.62–63; Theorem 9.1 pp.64–65; Proposition 9.11 pp.70–71; Lemma 9.12 pp.71–74; Proposition 9.13 pp.74–75; Remark 9.21 p.81; Theorem 10.5 pp.88–89; Proposition 10.8 pp.92–94. Also original PDF Theorem 5.4(iii) p.32 and its flat-character proof p.35; Theorem 9.1(vi) p.65; Proposition 9.20 p.80; Corollary 9.22 p.81; Remark9.27 p.83. The original PDF, not the transcription, governs the comparison.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_01_INVARIANTS:C2.1|AC26", "terms_searched": ["Bott", "Aeppli", "double complex", "McHugh", "Angella"], "hit_counts": {"Bott": 0, "Aeppli": 0, "double complex": 0, "McHugh": 0, "Angella": 1}}, "full_statement_found": false, "kind": "bounded_negative", "locator": "", "relation": "The precise result was not found in the explicitly listed original-source sections and statement searches. This is not a claim of absence from unread sections or from the literature as a whole."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "citation_key": "Engel2026", "original_source": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "source_sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "actual_reading_scope": "S6.tex §1 lines235–280; §2 lines288–390; main-thm lines882–910; integral homology lines1617–1643; remarks1647–1725.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_01_INVARIANTS:C2.1|E26", "terms_searched": ["Bott", "Aeppli", "double complex", "McHugh", "Angella"], "hit_counts": {"Bott": 0, "Aeppli": 0, "double complex": 0, "McHugh":