{"row_key": "S6_01_INVARIANTS:C3.4", "source_compendium_paper": "I", "source_compendium_label": "inv:C3.4", "source_file": "fragments/part_C.tex, Statement C3.4", "source_line": 4593, "source_section": "Fr\"olicher, Bott--Chern, Aeppli, and Hermitian metrics", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[Non-K\"ahler degrees and the precise degreewise statement]\label{inv:C3.4}
For $k=0,\ldots,6$ the non-K\"ahler degrees are
\begin{equation}\label{inv:eq:C-delta}
(\Delta^k)=(0,2,2+2h,4h,2+2h,2,0).
\end{equation}
If $h\ge1$, the two maps
$\bigoplus_{p+q=k}H^{p,q}_{BC}\to H^k_{\mathrm{dR}}(X;\C)
\to\bigoplus_{p+q=k}H^{p,q}_A$
are both isomorphisms exactly for $k=0,6$.
For the weaker assertion that a $d$-exact pure $d$-closed form of
degree $k$ is $\partial\bar\partial$-exact, the valid degrees are
$k=0,1,6$, and also $k=3,4$ if $h=0$.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "citation_key": "AC2026", "original_source": "sources/original/AC26_original_manuscript.pdf", "source_sha256": "283bba102dd1d5dc346af81b28145bdaaea6654398d5032e76e97bafb9a858f2", "actual_reading_scope": "Attached original PDF: Remark 1.3 p.5; Proposition 7.27 pp.62–63; Theorem 9.1 pp.64–65; Proposition 9.11 pp.70–71; Lemma 9.12 pp.71–74; Proposition 9.13 pp.74–75; Remark 9.21 p.81; Theorem 10.5 pp.88–89; Proposition 10.8 pp.92–94. Also original PDF Theorem 5.4(iii) p.32 and its flat-character proof p.35; Theorem 9.1(vi) p.65; Proposition 9.20 p.80; Corollary 9.22 p.81; Remark9.27 p.83. The original PDF, not the transcription, governs the comparison.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_01_INVARIANTS:C3.4|AC26", "terms_searched": ["Bott", "Aeppli", "Picard", "Green", "balanced", "Gauduchon", "SKT", "astheno", "twelve"], "hit_counts": {"Bott": 0, "Aeppli": 0, "Picard": 0, "Green": 0, "balanced": 0, "Gauduchon": 0, "SKT": 0, "astheno": 0, "twelve": 1}}, "full_statement_found": false, "kind": "bounded_negative", "locator": "", "relation": "The precise result was not found in the explicitly listed original-source sections and statement searches. This is not a claim of absence from unread sections or from the literature as a whole."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "citation_key": "Engel2026", "original_source": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "source_sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "actual_reading_scope": "S6.tex §1 lines235–280; §2 lines288–390; main-thm lines882–910; integral homology lines1617–1643; remarks1647–1725.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_01_INVARIANTS:C3.4|E26", "terms_searched": ["Bott", "Aeppli", "Picard", "Green", "balanced", 