{"row_key": "S6_03_CDP:A.3.2", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.3.2", "source_file": "sections/part_A.tex; Statement A.3.2", "source_line": 3083, "source_section": "Cotangent torsion, conductor and the printed endpoint error", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Counterexample", "source_statement": "\begin{proposition}[Counterexample: Vanishing on the support alone does not imply vanishing on a multiple fibre]\label{cdp:st:A.3.2}
There is a compact smooth complex threefold $g:Y\to\PP^1$ with connected general fibre an abelian surface and a smooth fibre support $S$ of multiplicity $m$, for every $m\ge3$, and a line bundle $B$ on $Y$, such that
\[
H^0(S,(\Omega_Y^1\otimes B)|_S)=0,
\qquad h^0(mS,(\Omega_Y^1\otimes B)|_{mS})=3.
\tag{A.12}\label{cdp:eq:A.12}
\]
Its conormal has exact order $m$. The replacement is (A.10)--(A.11), with the graded twists retained.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["multiple fibre", "multiple fiber", "nilpotent"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.3.2|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 10}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 13}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["multiple fibre", "multiple fiber", "nilpotent"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.3.2|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 4}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["multiple fibre", "multiple fiber", "nilpotent"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.3.2|DGKX_v1", "searched_files": [{"path":