{"row_key": "S6_03_CDP:A.3.4", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.3.4", "source_file": "sections/part_A.tex; Statement A.3.4", "source_line": 3141, "source_section": "Cotangent torsion, conductor and the printed endpoint error", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[The smooth-multiple assertion of Remark 7.2]\label{cdp:st:A.3.4}
Under the hypotheses of CDP20 Proposition~7.3, let $mS$ be a full fibre whose reduced support $S$ is smooth. For every real irrational transgression parameter $r$ of \ref{cdp:st:D.1.9},
\[
 H^0\bigl(mS,(\Omega_Y^1\otimes L_r)|_{mS}\bigr)=0.
 \tag{A.15a}\label{cdp:eq:A.15a}
\]
The same simultaneous vanishing on all such fibres holds on the complement of a proper complex analytic subset of $\Pic(Y)$. The assertion includes the entire scheme-theoretic fibre, with every nilpotent layer.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["smooth.multiple", "root cover", "unitary"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.3.4|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 1}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 1}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["smooth.multiple", "root cover", "unitary"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.3.4|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 0}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["smooth.multiple", "root cover", "unitary"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.3.4|DGKX_v1", "searched_files": [{"path": "sources/papers/