{"row_key": "S6_03_CDP:A.3.5", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.3.5", "source_file": "sections/part_A.tex; Statement A.3.5", "source_line": 3171, "source_section": "Cotangent torsion, conductor and the printed endpoint error", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[Every reducible full fibre has generic ambient vanishing]\label{cdp:st:A.3.5}
Let $Y$ be a smooth compact complex threefold with $H^2(Y,\Q)=0$, and let $F=\sum_i m_iS_i$ be an effective Cartier divisor with connected reducible support. Every connected component of $\Pic(Y)$ contains a dense open subset, with proper closed analytic complement, on which
\[
 H^0(F,(\Omega_Y^1\otimes L)|_F)=0.
 \tag{A.15b}\label{cdp:eq:A.15b}
\]
The multiplicities may be unequal. For a proper connected fibration over a compact curve, the vanishing is simultaneous on all reducible full fibres after intersecting finitely many such open sets. Consequently a full fibre with ambient sections for every Picard twist has irreducible support.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["reducible", "ambient", "generic"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.3.5|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 29}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 33}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["reducible", "ambient", "generic"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.3.5|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 2}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["reducible", "ambient", "generic"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.3.5|DGKX_v1", "searched_files": [{"path": "sources/papers/arXiv_2610.00250v1_Du_Guo_Kusakabe_Xie_src/v5oka_maps_modifications_deformations.tex", "sha256": "924a4a72d80793927f3104121a44786ea2b9869ae6ea2bca5a6a69553ab2884e", "hit_count": 51}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#DGKX_v1", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_elsewhere": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "matches": [], "cited_opened_inputs": [], "additional_attached_search_record": "deliverables/work/cdp_audit/credit_elsewhere_searches_239.json#A.3.5", "terms_searched": ["reducible", "ambient", "generic"], "corpus_size_files": 43, "bounded_absence_statement": "Beyond the explicit positive matches and opened general inputs, no full counterpart was identified in the executed attached-source searches and stated context readings. This is not an exhaustive priority search of all literature.", "existing_scoped_credit_notes": ""}"}, "historical_source_notes": "SOURCE STATEMENT: Every reducible full fibre has generic ambient vanishing | SOURCE STATUS: Proved | SOURCE NOTES: Arbitrary unequal multiplicities; every Picard component; persistence forces irreducible support. | proof_sha256: 3fa7c9d605aecaf2fbefb3dc60ed007a2ec20dca506f25798d5739ee2eb781f0 | Explicit source comparison: work/cdp_audit/credit_comparison_239.json | Final II source-to-print retention: complete normalized canonical blocks retained; exact mathematical/citation changes separately reviewed in records/II_editorial_mathematical_changes.json, II_working_supplement_root_changes.json and II_positive_credit_changes.json.", "pre_current_event_status": "historical record: Proved; current-writing proof review pending", "current_event_sources": ["records/sign_events.tsv"]}

{"row_key": "S6_03_CDP:A.4.1", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.4.1", "source_file": "sections/part_A.tex; Statement A.4.1", "source_line": 3210, "source_section": "Cotangent torsion, conductor and the printed endpoint error", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[Both fibre groups on the specified $W$]\label{cdp:st:A.4.1}
For the reduced normal-crossings fibre $W$ with normalization $\eta:\operatorname{dP}_6\to W$ in the specified threefold $X$, and every $L\in\Pic(X)$, put $A=(K_X\otimes L^{-1})|_W$. Then
\[
H^0(W,Q\otimes A)=0,
\qquad H^0(W,\Omega_X^1|_W\otimes A)\simeq\C.
\tag{A.15}\label{cdp:eq:A.15}
\]
The same two conclusions hold with $A=B|_W$ for every $B\in\Pic(X)$.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "found_in_checked_scope", "full_statement_found": false, "terms_searched": ["10.5", "torsion.free", "normalisation"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.1|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 68}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 73}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [{"baseline": "AC26", "relation": "partial_known_input", "locator": "Theorem10.5 pp88–89 and section10.4 pp89–90", "comparison": "The torsion-free vanishing and nonzero ambient fibre section on W are known. The exact ambient dimension1 is additional."}], "relation": "The torsion-free vanishing and nonzero ambient fibre section on W are known. The exact ambient dimension1 is additional."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["10.5", "torsion.free", "normalisation"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.1|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 0}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["10.5", "torsion.free", "normali