{"row_key": "S6_03_CDP:A.5.3", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.5.3", "source_file": "sections/part_A.tex; Statement A.5.3", "source_line": 3528, "source_section": "Normalization, conductor genus and local torus exclusions", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[The effective conductor divisor on a minimal resolution]\label{cdp:st:A.5.3}
Let $S$ be a compact reduced hypersurface in a smooth threefold, let $\eta:\coprod_i T_i\to S$ be its normalization, and let $\pi_i:Z_i\to T_i$ be the minimal resolutions. Put $h_i=\eta\pi_i$. There are canonical effective integral divisors $D_i$ on $Z_i$ with
\[
 \omega_{Z_i}(D_i)\simeq h_i^*\omega_S.
 \tag{A.25}\label{cdp:eq:A.25}
\]
The nonexceptional part of $D_i$ is exactly the divisorial conductor, with its scheme-theoretic multiplicities. When $S\subset Y$ and $H^2(Y,\Q)=0$, every $K_{Z_i}+D_i$ has rational first Chern class zero. A ruled $Z_i\to B$ with $g(B)\ge2$ then has
\[
 D_i=2C+V,
 \tag{A.26}\label{cdp:eq:A.26}
\]
where $C$ is a section and $V$ is vertical. In the case where $C$ is $\pi_i$-exceptional, $\eta^*(L|_S)|_{T_i}$ is trivial for every $L\in\Pic(Y)$.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["effective.conductor", "anticanonical", "resolution"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.5.3|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 9}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 9}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["effective.conductor", "anticanonical", "resolution"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.5.3|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 2}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["effective.conductor", "anticanonical", "resolution"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.5.3|DGKX_v1", "searched_files": [{"path": "sources/papers/arXiv_2610.00250v1_Du_Guo_Kusakabe_Xie_src/v5oka_maps_modifications_deformations.tex", "sha256": "924a4a72d80793927f3104121a44786ea2b9869ae6ea2bca5a6a69553ab2884e", "hit_count": 30}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#DGKX_v1", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_elsewhere": "{"status": "found_in_checked_scope", "full_statement_found": false, "matches": [{"baseline": "elsewhere", "relation": "partial_known_input", "locator": "Campana–Demailly–Peternell2020 Lemma4.6 p685; Furushima1993 section1 Lemma1.1/Corollary1.4 p5", "comparison": "The conductor-canonical calculation is known. Furushima is a narrower projective comparison; the analytic exceptional correction is proved independently with the negative intersection matrix."}], "cited_opened_inputs": [{"citation_key": "Furushima1993", "relation": "cited original input or explicit comparison; not by itself a match of the full receiving statement", "source_opening_records": [{"record_file": "deliverables/work/invariants_arithmetic/references_verified.json", "key": "Furushima1993", "status": "verified_for_stated_use", "locators": ["Printed p5 (PDF page7), Section1 hypotheses, Lemma1.1(i)-(vi), Definition1.2, Lemma1.3 and Corollary1.4 with its complete short proof; original scan visually opened."], "scope": "Lemma1.1 assumes an irreducible nonnormal reduced projective Gorenstein surface. Corollary1.4 follows under the additional K3-type assumptions omega_S=O_S and h1(O_S)=0 and a very ample polarization. These assumptions do not cover the general compact analytic divisor in CDP. The citation is a comparison only; its corollary is not imported as the general theorem. The actual independent receiving proof establishes its broader claim by conductor duality and the negative definite exceptional matrix.", "reader": "GPT-6 Astra (OpenAI, ChatGPT Pro mode)"}]}], "additional_attached_search_record": "deliverables/work/cdp_audit/credit_elsewhere_searches_239.json#A.5.3", "terms_searched": ["effective.conductor", "anticanonical", "resolution"], "corpus_size_files": 43, "bounded_absence_statement": "Beyond the explicit positive matches and opened general inputs, no full counterpart was identified in the executed attached-source searches and stated context readings. This is not an exhaustive priority search of all literature.", "existing_scoped_credit_notes": ""}"}, "historical_source_notes": "SOURCE STATEMENT: The effective conductor divisor on a minimal resolution | SOURCE STATUS: Proved | SOURCE NOTES: Intermediate geometric reduction: effective conductor on the minimal normalization resolution and exact coefficient-two ruled case. The remaining ruled obstruction is closed by A.5.12–13 and root C4e; primary Kodaira general fibres are excluded by C.3.10. | remarks: Rank-one-reflexivity uses normal surface Cohen–Macaulayness; sign of M a=-v and a>=0 checked explicitly. | proof_sha256: db2d60e080254e66da39c85c33ffd027e55acd3e18963fcc56d559e13cc7d663 | Explicit source comparison: work/cdp_audit/credit_comparison_239.json | Final II source-to-print retention: complete normalized canonical blocks retained; exact mathematical/citation changes separately reviewed in records/II_editorial_mathematical_changes.json, II_working_supplement_root_changes.json and II_positive_credit_changes.json.", "pre_current_event_status": "historical record: Proved; current-writing proof review pending", "current_event_sources": ["records/sign_events.tsv"]}

{"row_key": "S6_03_CDP:A.5.6", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.5.6", "source_file": "sections/part_A.tex; Statement A.5.6", "source_line": 3626, "source_section": "Normalization, conductor genus and local torus exclusions", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[Uniform negative-degree vanishing for a fixed vector bundle]\label{cdp:st:A.5.6}
Let $Z$ be a compact smooth complex surface, $\omega$ a Gauduchon metric, and $E$ a fixed holomorphic vector bundle. There is a real constant $b(E,\omega)$ such that
\[
 \deg_\omega P<b(E,\omega)
 \quad\Longrightarrow\quad H^0(Z,E\otimes P)=0
 \tag{A.30}\label{cdp:eq:A.30}
\]
for every holomorphic line bundle $P$. Thus persistence of sections of $E\otimes h^*L$ for every $L\in\Pic(Y)$ forces $\deg_\omega h^*L=0$ for every $L$, for any holomorphic map $h:Z\to Y$. Persistence on one Picard component already forces degree zero on the pullback of $\Pic^0(Y)$. Under $H^2(Y,\Q)=0$, it forces degree zero and unitary flatness for every ambient Picard pullback. On a class VII surface $Z$ with $H^2(Y,\Z)=0$, the entire holomorphic Picard pullback is the zero map.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["Gauduchon", "negative.degree", "Bochner"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.5.6|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 1}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 1}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["Gauduchon", "negative.degree", "Bochner"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.5.6|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 0}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["Gauduchon", "negative.degree", "Bochner"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.5.6|DGKX_v1", "searched_files": [{"path": "sources/papers/arXiv_2610.00250v1_Du_Guo_Kusakabe_Xie_src/v5oka_maps_modifications_deformations.tex", "sha256": "924a4a72d80793927f3104121a44786ea2b9869ae6ea2bca5a6a69553ab2884e", "hit_count": 0}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#DGKX_v1", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_elsewhere": "{"status": "found_in_checked_scope", "full_statement_found": false, "matches": [], "cited_opened_inputs": [{"citation_key": "Teleman2006", "relation": "cited original input or explicit comparison; not by itself a match of the full receiving statement", "source_opening_records": [{"record_file": "deliverables/work/invariants_arithmetic/references_verified.json", "key": "Teleman2006", "status": "verified_for_stated_use", "locators": ["Lemma2.3(1)-(2), complete proofs on arXiv pp5-6; compact complex surface and Gauduchon metric hypotheses preceding the lemma."], "scope": "The exact curvature form with zero Gauduchon degree is made primitive by the scalar equation, then is exact and anti-selfdual and hence zero. Part(2) injects H1(iR) into H1(O). Multiplication by i matches the manuscript exponential convention. No classVII/GSS assumption is needed for this lemma. The source display has an extraneous =0 at the end of its scalar equation; the proof and the receiving manuscript use the intended nonzero mean-zero right hand side.", "reader": "GPT-6 Astra (OpenAI, ChatGPT Pro mode)"}]}], "additional_attached_search_record": "deliverables/work/cdp_audit/credit_elsewhere_searches_239.json#A.5.6", "terms_searched": ["Gauduchon", "negative.degree", "Bochner"], "corpus_size_files": 43, "bounded_absence_statement": "Beyond the explicit positive matches and opened general inputs, no full counterpart was identified in the executed attached-source searches and stated context readings. This is not an exhaustive priority search of all literature.", "existing_scoped_credit_notes": ""}"}, "historical_source_notes": "SOURCE STATEMENT: Uniform negative-degree vanishing for a fixed vector bundle | SOURCE STATUS: Proved | SOURCE NOTES: Exact degree bound and class VII Picard consequence; A.5.5 is owned by the critical-curve agent in a separate fragment. | proof_sha256: 617f771dbd47348c58651cb6091d18d0dc3cba700b09a431c6a3b944229c57e4 | Explicit source comparison: work/cdp_audit/credit_comparison_239.json | Final II source-to-print retention: complete normalized canonical blocks retained; exact mathematical/citation changes separately reviewed in records/II_editorial_mathematical_changes.json, II_working_supplement_root_changes.json and II_positive_credit_changes.json.", "pre_current_event_status": "historical record: Proved; current-writing proof review pending", "current_event_sources": ["records/sign_events.tsv"]}

{"row_key": "S6_03_CDP:A.4.3", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.4.3", "source_file": "sections/part_A.tex; Statement A.4.3", "source_line": 3251, "source_section": "Cotangent torsion, conductor and the printed endpoint error", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[The omitted genus-one case for the standard rank-one fibre]\label{cdp:st:A.4.3}
Let $E$ be an elliptic curve, let $P\in\Pic(E)$, and let $T=\PP_E(\OO_E\oplus P)$ with its zero and infinity sections $D_0,D_\infty$. Glue $D_0$ to $D_\infty$ by a translation of $E$ to form the compact normal-crossings surface $S$, and denote its normalization by $\eta:T\to S$. Every line bundle $A$ on $S$ whose pullback $\eta^*A$ is topologically trivial satisfies
\[
H^0(S,\widetilde\Omega_S^1\otimes A)=
\begin{cases}\C,&A\simeq\OO_S,\\0,&A\not\simeq\OO_S.\end{cases}
\tag{A.16}\label{cdp:eq:A.16}
\]
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["genus.one", "rank.one", "singular fibre"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.3|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 12}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 13}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["genus.one", "rank.one", "singular fibre"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.3|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 0}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["genus.one", "rank.one", "singular fibre"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.3|DGKX_v1", "searched_files": [{"path": "sources/papers/arXiv_2610.00250v1_Du_Guo_Kusakabe_Xie_src/v5oka_maps_modifications_deformations.tex", "sha256": "924a4a72d80793927f3104121a44786ea2b9869ae6ea2bca5a6a69553ab2884e", "hit_count": 5}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#DGKX_v1", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_elsewhere": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "matches": [], "cited_opened_inputs": [], "additional_attached_search_record": "deliverables/work/cdp_audit/credit_elsewhere_searches_239.json#A.4.3", "terms_searched": ["genus.one", "rank.one", "singular fibre"], "corpus_size_files": 43, "bounded_absence_statement": "Beyond the explicit positive matches and opened general inputs, no full counterpart was identified in the executed attached-source searches and stated context readings. This is not an exhaustive priority search of all literature.", "existing_scoped_credit_notes": ""}"}, "historical_source_notes": "SOURCE STATEMENT: The omitted genus-one case for the standard rank-one fibre | SOURCE STATUS: Proved | SOURCE NOTES: See records/A_notes.md for exact scope and verification. | proof_sha256: cd38b6e8905c120bcf3794bb36738223d0dab449f81135a178cbdf40940891b6 | remarks: The relative cotangent has degree -2 on ruling fibres. The only possible pulled-back form comes from the elliptic base; translation preserves it, and descent forces the constant gluing scalar to be one. Thus the exceptional genus-one case is exactly the trivial line, for arbitrary degree of the ruling line. | Explicit source comparison: work/cdp_audit/credit_comparison_239.json | Final II source-to-print retention: complete normalized canonical blocks retained; exact mathematical/citation changes separately reviewed in records/II_editorial_mathematical_changes.json, II_working_supplement_root_changes.json and II_positive_credit_changes.json."}

{"row_key": "S6_03_CDP:A.4.6", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.4.6", "source_file": "sections/part_A.tex; Statement A.4.6", "source_line": 3328, "source_section": "Cotangent torsion, conductor and the printed endpoint error", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[Euler numbers of these irreducible normal-crossings fibres]\label{cdp:st:A.4.6}
For $S$ in \ref{cdp:st:A.4.5},
\[
e(S)=\begin{cases}
2,&\widetilde S\text{ is rational},\\
0,&\widetilde S\text{ is elliptic ruled or Hopf}.
\end{cases}
\tag{A.18}\label{cdp:eq:A.18}
\]
Thus an arbitrary compact torus fibration whose fibres are irreducible reduced normal-crossings surfaces or multiples of smooth surfaces of Euler number zero has
\[
c_3(Y)=e(Y)=2r,
\tag{A.19}\label{cdp:eq:A.19}
\]
where $r$ is the number of rational-normalization fibres. For $b_1(Y)=b_2(Y)=0$, one has $r\in\{0,1\}$ and $b_3(Y)=2-2r$.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["normal.crossing", "Euler", "irreducible"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.6|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 40}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 47}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["normal.crossing", "Euler", "irreducible"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.6|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 4}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["normal.crossing", "Euler", "irreducible"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.6|DGKX_v1", "searched_files": [{"path": "sources/papers/a