{"row_key": "S6_03_CDP:A.4.7", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.4.7", "source_file": "sections/part_A.tex; Statement A.4.7", "source_line": 3357, "source_section": "Cotangent torsion, conductor and the printed endpoint error", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[Unitary-flat differentials on every compact reduced complex surface]\label{cdp:st:A.4.7}
Let $S$ be a compact reduced complex surface, let $\mathbb A$ be a rank-one unitary complex local system on its underlying topological space, and let $A=\mathbb A\otimes_{\C}\OO_S$ be its associated holomorphic line bundle. There is a canonical complex-linear injection
\[
 H^0(S,\widetilde\Omega_S^1\otimes A)
       \longrightarrow H^1(S,\mathbb A).
 \tag{A.20}\label{cdp:eq:A.20}
\]
The construction uses continuous local primitives that are holomorphic on the normalization; it does not assert that those primitives are holomorphic on a non-seminormal surface.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["unitary.flat", "holomorphic.*form", "Stokes"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.7|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 26}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 17}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["unitary.flat", "holomorphic.*form", "Stokes"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.7|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 0}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["unitary.flat", "holomorphic.*form", "Stokes"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.7|DGKX_v1", "searched_files": [{"path": "sources/papers/arXiv_2610.00250v1_Du_Guo_Kusakabe_Xie_src/v5oka_maps_modifications_deformations.tex", "sha256": "924a4a72d80793927f3104121a44786ea2b9869ae6ea2bca5a6a69553ab2884e", "hit_count": 2}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#DGKX_v1", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_elsewhere": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "matches": [], "cited_opened_inputs": [], "additional_attached_search_record": "deliverables/work/cdp_audit/credit_elsewhere_searches_239.json#A.4.7", "terms_searched": ["unitary.flat", "holomorphic.*form", "Stokes"], "corpus_size_files": 43, "bounded_absence_statement": "Beyond the explicit positive matches and opened general inputs, no full counterpart was identified in the executed attached-source searches and stated context readings. This is not an exhaustive priority search of all literature.", "existing_scoped_credit_notes": ""}"}, "historical_source_notes": "SOURCE STATEMENT: Unitary-flat differentials on every compact reduced complex surface | SOURCE STATUS: Proved | SOURCE NOTES: See records/A_notes.md for exact scope and verification. | proof_sha256: 8a2df63ae6690725d031ffed2edf6768002f3938af8b05d801a03e5928380355 | Explicit source comparison: work/cdp_audit/credit_comparison_239.json | Final II source-to-print retention: complete normalized canonical blocks retained; exact mathematical/citation changes separately reviewed in records/II_editorial_mathematical_changes.json, II_working_supplement_root_changes.json and II_positive_credit_changes.json.", "pre_current_event_status": "historical record: Proved; current-writing proof review pending", "current_event_sources": ["records/sign_events.tsv"]}

{"row_key": "S6_03_CDP:A.4.8", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.4.8", "source_file": "sections/part_A.tex; Statement A.4.8", "source_line": 3393, "source_section": "Cotangent torsion, conductor and the printed endpoint error", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[The torsion-free cotangent assertion for arbitrary singular supports in a torus fibration]\label{cdp:st:A.4.8}
Let $g:Y\to\PP^1$ be a proper surjective holomorphic map with connected fibres from a smooth compact complex threefold with $b_1(Y)=b_2(Y)=0$, and suppose its general fibre is a complex two-torus. Let $L_r=\exp(2\pi\mathrm i r\beta)\in\Pic^0(Y)$ be the transgression family constructed in \ref{cdp:st:D.1.9}. For every real irrational $r$ and every reduced fibre support $S=(Y_c)_{\rm red}$,
\[
 H^1(S,\mathbb A_{r,S})=0,
 \qquad
 H^0(S,\widetilde\Omega_S^1\otimes L_r|_S)=0,
 \tag{A.21}\label{cdp:eq:A.21}
\]
where $\mathbb A_{r,S}$ is the unitary local system whose associated holomorphic line is $L_r|_S$. In particular this proves Equation~(11) of CDP20 for all singular reduced fibre supports in the torus case, with no assumption on their singularities or their scheme-theoretic multiplicities.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["singular.support", "local.system", "Koszul"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.8|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 7}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 7}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["singular.support", "local.system", "Koszul"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.8|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 8}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["singular.support", "local.system", "Koszul"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.8|DGKX_v1", "searched_files": [{"path": "sources/p