{"row_key": "S6_03_CDP:A.4.9", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:A.4.9", "source_file": "sections/part_A.tex; Statement A.4.9", "source_line": 3425, "source_section": "Cotangent torsion, conductor and the printed endpoint error", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[CDP20 Proposition 7.3 with a complete replacement proof]\label{cdp:st:A.4.9}
Let $Y$ be a connected smooth compact complex threefold with $H^1(Y,\Z)=H^2(Y,\Z)=0$, algebraic dimension one and holomorphic algebraic reduction $g:Y\to C$. There is a dense open subset of $\Pic(Y)$, whose complement is a proper complex analytic subset, such that
\[
 H^0\bigl((Y_c)_{\rm red},
       \widetilde\Omega^1_{(Y_c)_{\rm red}}\otimes L|_{(Y_c)_{\rm red}}\bigr)=0
 \tag{A.23}\label{cdp:eq:A.23}
\]
for every singular reduced fibre support and every $L$ in that subset. In fact the transgression twists $L_r$ of \ref{cdp:st:D.1.9} satisfy \eqref{cdp:eq:A.23} on every reduced fibre support, including smooth and reducible supports, for every real irrational $r$.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["Proposition 7.3", "Hopf", "Inoue", "Kodaira"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.9|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 9}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 10}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["Proposition 7.3", "Hopf", "Inoue", "Kodaira"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.9|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 11}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["Proposition 7.3", "Hopf", "Inoue", "Kodaira"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#A.4.9|DGKX_v1", "searched_files": [{"path": "sources/papers/arXiv_2610.00250v1_Du_Guo_Kusakabe_Xie_src/v5oka_maps_modifications_deformations.tex", "sha256": "924a4a72d80793927f3104121a44786ea2b9869ae6ea2bca5a6a69553ab2884e", "hit_count": 13}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#DGKX_v1", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_elsewhere": "{"status": "found_in_checked_scope", "full_statement_found": false, "matches": [{"baseline": "elsewhere", "relation": "known_statement_repaired_and_strengthened", "locator": "Campana–Demailly–Peternell2020 Proposition7.3 pp693–694", "comparison": "The first generic torsion-free-cotangent conclusion is already asserted. Its printed proof has a false constant-twist genus inference. The receiving full replacement proof and irrational-uniform-transgression strengthening are distinct; describe this as a correction/extension, not a wholly new proposition."}], "cited_opened_inputs": [{"citation_key": "Albanese2020", "relation": "cited original input or explicit comparison; not by itself a match of the full receiving statement", "source_opening_records": [{"record_file": "deliverables/work/cdp_audit/references_verified.json", "key": "Albanese2020", "status": "verified in the specified scope", "locators": ["arXiv2005.09494v2, 6November2020, section2.1.1 and Theorem2.2, p3", "Entire section2.1.2, pp3–6, including all explicit generators, conjugation relations, nilmanifold constructions and Proposition2.3"], "scope": "The Hopf topology and finite-cover statements were opened in the original author article; they are established inputs credited there to Kodaira and Kato. Read the complete displayed mapping-torus constructions: SM has Z3 kernel and M-transpose monodromy, while S-plus/minus has a Heisenberg lattice and a circle bundle with nonzero Chern class r over T2. The displayed conjugations give the quotient eigenvalues alpha,alpha^-1 or alpha,-alpha^-1; the centre is inverted in the minus case. These exact hypotheses match the Gysin and twisted Wang arguments in A4.9. No Yamabe theorem or proof is imported or audited by this record.", "reader": "GPT-6 Astra (OpenAI, ChatGPT Pro mode), effort Pro, writing run; 17 November 2026 UTC"}]}, {"citation_key": "SS2002", "relation": "cited original input or explicit comparison; not by itself a match of the full receiving statement", "source_opening_records": [{"record_file": "deliverables/work/cdp_audit/references_verified.json", "key": "SS2002", "status": "verified in the specified scope", "locators": ["arXivmath/0001077v2, §1 pp2–3: degree, intrinsic Picard quotient and (d,j,alpha) coordinates", "Definition2.1 and Propositions2.4–2.6 with full proofs pp4–6", "Proposition3.1 with full contraction-normal-form proof pp6–7", "Proposition4.1 with full proof p13"], "scope": "The admissibility definition requires irreducible normal crossings, d-semistability and trivial dualizing line, without assuming an existing Kodaira smoothing. The normalized surface cases, diagonal Hopf criterion and ruled translation criterion match these hypotheses. In §1 the positive-degree class fixes the inversion ambiguity in C*.", "reader": "GPT-6 Astra (OpenAI, ChatGPT Pro mode), effort Pro, writing run; 17 November 2026 UTC"}]}], "additional_attached_search_record": "deliverables/work/cdp_audit/credit_elsewhere_searches_239.json#A.4.9", "terms_searched": ["Proposition 7.3", "Hopf", "Inoue", "Kodaira"], "corpus_size_files": 43, "bounded_absence_statement": "Beyond the explicit positive matches and opened general inputs, no full counterpart was identified in the executed attached-source searches and stated context readings. This is not an exhaustive priority search of all literature.", "existing_scoped_credit_notes": ""}"}, "historical_source_notes": "SOURCE STATEMENT: CDP20 Proposition 7.3 with a complete replacement proof | SOURCE STATUS: Proved | SOURCE NOTES: Full Proposition7.3 proved; the printed proof remains invalid at the explicitly refuted step. | proof_sha256: c8ccac4ff43507e3b587b8385be9d0d3d49b253b4d21f76a6f54ce0d31247bc2 | Explicit source comparison: work/cdp_audit/credit_comparison_239.json | Final II source-to-print retention: complete normalized canonical blocks retained; exact mathematical/citation changes separately reviewed in records/II_editorial_mathematical_changes.json, II_working_supplement_root_changes.json and II_positive_credit_changes.json.", "pre_current_event_status": "historical record: Proved; current-writing proof review pending", "current_event_sources": ["records/sign_events.tsv"]}

{"row_key": "S6_03_CDP:C.3.3", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:C.3.3", "source_file": "sections/part_C1_C3.tex; Statement C.3.3", "source_line": 1318, "source_section": "Complete smooth-fibre classification and actual Hopf occurrence", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Counterexample", "source_statement": "\begin{proposition}[Refuted surface assertion, with explicit example]\label{cdp:st:C.3.3}

The assertion that a secondary Hopf surface has torsion in
$H_1(-;\Z)$ is false. There is a secondary Hopf surface $Q_H$ with
$H_1(Q_H;\Z)=\Z$ and $H^2(Q_H;\Z)=0$.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["secondary.Hopf", "Hopf.surface", "homology"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.3.3|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 34}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 37}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["secondary.Hopf", "Hopf.surface", "homology"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.3.3|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 18}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["secondary.Hopf", "Hopf.surface", "homology"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.3.3|DGKX_v1", "searched_files": [{"path": "source