{"row_key": "S6_03_CDP:C.3.7", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:C.3.7", "source_file": "sections/part_C1_C3.tex; Statement C.3.7", "source_line": 1407, "source_section": "Complete smooth-fibre classification and actual Hopf occurrence", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[Proved exclusion of bielliptic fibres]\label{cdp:st:C.3.7}

A compact complex threefold $Y$ with $b_1(Y)=b_2(Y)=0$ has no
proper connected-fibre holomorphic map to a compact curve whose
general fibre is bielliptic.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["bielliptic", "Kawai", "nonexist"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.3.7|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 15}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 15}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["bielliptic", "Kawai", "nonexist"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.3.7|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 12}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["bielliptic", "Kawai", "nonexist"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.3.7|DGKX_v1", "searched_files": [{"path": "sources/papers/arXiv_2610.00250v1_Du_Gu