{"row_key": "S6_03_CDP:C.2.NC.2", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:C.2.NC.2", "source_file": "sections/part_C2_NC.tex; Statement C.2.NC.2", "source_line": 19237, "source_section": "Normal-crossing topology and canonical-flat component comparisons", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[The normalized double curves and the coherent Euler formula]\label{cdp:st:C.2.NC.2}
Let $S$ be a connected compact normal-crossings divisor in a smooth compact complex threefold $Y$ with $H^2(Y,\Q)=0$. Write $\nu:\coprod_iT_i\to S$ for normalization, $D_i\subset T_i$ for its conductor, $C_\alpha$ for the connected components of the normalization of the double locus, and $\tau$ for the number of triple points. Let $R_\alpha$ be the reduced divisor on $C_\alpha$ of preimages of triple points, counted separately for the three double-curve branches at each triple point. Then
\[
 e(C_\alpha)=\deg R_\alpha,\qquad
 \sum_\alpha e(C_\alpha)=3\tau,
 \qquad
 \sum_i\chi(T_i,\OO_{T_i})=\frac{\tau}{2}.
 \tag{C.NC.4}\label{cdp:eq:C.NC.4}
\]
In particular every normalized double curve has genus at most one, and $\tau$ is even. The remaining topological identities are
\[
\begin{aligned}
 \sum_i e(D_i)&=2\sum_\alpha e(C_\alpha)-3\tau,\\
 e(S)&=\sum_i e(T_i)-\sum_\alpha e(C_\alpha)+\tau.
\end{aligned}
 \tag{C.NC.5}\label{cdp:eq:C.NC.5}
\]
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["normal.crossing", "multiplicit", "Euler"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.2.NC.2|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 30}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 35}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["normal.crossing", "multiplicit", "Euler"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.2.NC.2|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 11}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["normal.crossing", "multiplicit", "Euler"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.2.NC.2|DGKX_v1", "searched_files": [{"path": "source