{"row_key": "S6_03_CDP:C.2.CR.5", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:C.2.CR.5", "source_file": "sections/part_C2_contracted.tex; Statement C.2.CR.5", "source_line": 13765, "source_section": "Irreducible and reducible torus-fibre Euler criteria", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[A contracted horizontal section is elliptic]\label{cdp:st:C.2.CR.5}
