\]
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["contracted", "horizontal", "conductor", "elliptic", "contract"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.2.CR.5|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 48}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 61}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["contracted", "horizontal", "conductor", "elliptic", "contract"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#C.2.CR.5|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 32}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["contracted", "horizontal", "conductor", "elliptic", "contract"], "search_record": "deliverables/work/cdp_audit/credit_search