{"row_key": "S6_03_CDP:E3", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:E3", "source_file": "sections/part_E.tex; Statement E3", "source_line": 53522, "source_section": "Known source results re-derived", "placement_basis": "inventory kind and plan condition 2", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Cited/re-derived", "source_statement": "\begin{proposition}[Credited re-derivation: Excluded algebraic dimensions]\label{cdp:st:E3}
