[{"path": "sources/papers/arXiv_2610.00250v1_Du_Guo_Kusakabe_Xie_src/v5oka_maps_modifications_deformations.tex", "sha256": "924a4a72d80793927f3104121a44786ea2b9869ae6ea2bca5a6a69553ab2884e", "hit_count": 0}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#DGKX_v1", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_elsewhere": "{"status": "found_in_checked_scope", "full_statement_found": true, "matches": [{"baseline": "elsewhere", "relation": "full_known_consequence", "locator": "Campana–Demailly–Peternell1998 Lemma1.4; Lehn–Rollenske–Schinko2019 Theorem3.1/Corollary3.2", "comparison": "Moishezon b2>0 is the exact known lemma. The exclusion of a=2,3 and a nonholomorphic reduction on S6 is its direct combination with the known nonholomorphic-pencil theorem, not a new sphere exclusion."}], "cited_opened_inputs": [], "additional_attached_search_record": "deliverables/work/cdp_audit/credit_elsewhere_searches_239.json#E3", "terms_searched": ["Moishezon", "algebraic.dimension", "non.holomorphic"], "corpus_size_files": 43, "bounded_absence_statement": "Beyond the explicit positive matches and opened general inputs, no full counterpart was identified in the executed attached-source searches and stated context readings. This is not an exhaustive priority search of all literature.", "existing_scoped_credit_notes": "Opened original CDP98 Lemma1.4 and its complete proof in the supplied source; it is not Corollary1.2."}"}, "historical_source_notes": "SOURCE STATEMENT: Moishezon manifolds have b2>0; S6 excludes a=2,3 and nonholomorphic reduction | SOURCE STATUS: Proved | SOURCE NOTES: Only a=0 or a=1 can occur; existence outside known families is not claimed. | proof_sha256: a9642688f73f090a878f8807a60e155e879f5694a9b4ca569b01fc98ecd301d2 | remarks: A pushed-down ample divisor meets a pushed-down general curve with positive degree. On a six-sphere, E2 forbids an indeterminate meromorphic function; two independent holomorphic P1 maps would create one by the local quotient u/v. Thus a<=1, and any algebraic-reduction curve has genus zero. | Credit evidence (cdp_audit/result_audit.json): Opened original CDP98 Lemma1.4 and its complete proof in the supplied source; it is not Corollary1.2. | Explicit source comparison: work/cdp_audit/credit_comparison_239.json | Final II source-to-print retention: complete normalized canonical blocks retained; exact mathematical/citation changes separately reviewed in records/II_editorial_mathematical_changes.json, II_working_supplement_root_changes.json and II_positive_credit_changes.json."}

{"row_key": "S6_03_CDP:E4", "source_compendium_paper": "II", "source_compendium_label": "cdp:st:E4", "source_file": "sections/part_E.tex; Statement E4", "source_line": 53562, "source_section": "Known source results re-derived", "placement_basis": "inventory kind and plan condition 2", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Cited/re-derived", "source_statement": "\begin{proposition}[Credited re-derivation: Degree-one cohomological flatness over a curve]\label{cdp:st:E4}
For a proper surjective holomorphic map $g:Y\to C$ from a connected complex
manifold to a nonsingular curve with connected fibres,
$R^1g_*\mathcal O_Y$ is locally free and
$H^0(Y_c,\mathcal O_{Y_c})=\mathbb C$ for every scheme-theoretic fibre.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["local.freeness", "locally.free", "Proposition 5.1"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#E4|AC26", "searched_files": [{"path": "sources/original/AC26_transcription.tex", "sha256": "9e87e12175c70040ed66ab6513172a1f952c96205601c0910f48712c42445170", "hit_count": 18}, {"path": "sources/external/root/AC26_pdf_text.txt", "sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 24}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#AC26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["local.freeness", "locally.free", "Proposition 5.1"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#E4|E26", "searched_files": [{"path": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hit_count": 0}], "actual_reading_scope_record": "deliverables/work/cdp_audit/credit_context_readings.json#E26", "matches": [], "relation": "No full matching receiving statement was identified within the listed queries and actually read contexts. Related construction data or general lemmas may occur; the saved hit list is not a claim that every hit was read."}", "found_in_DGKX_v1": "{"status": "not_found_in_checked_scope", "full_statement_found": false, "terms_searched": ["local.freeness", "locally.free", "Proposition 5.1"], "search_record": "deliverables/work/cdp_audit/credit_searches_239.json#E4|DGKX_v1", "searched_files": [{"pat