{"row_key": "S6_04_MAPS_MANIFOLDS:B.3.1", "source_compendium_paper": "III", "source_compendium_label": "maps:src:B.3.1", "source_file": "sections/maps.tex, Theorem B.3.1", "source_line": 546, "source_section": "Sphere maps, framings and homotopy classes", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Theorem", "source_statement": "\begin{theorem}\label{maps:src:B.3.1}

