{"row_key": "S6_04_MAPS_MANIFOLDS:D.3.4", "source_compendium_paper": "III", "source_compendium_label": "maps:src:D.3.4", "source_file": "sections/manifolds.tex", "source_line": 41449, "source_section": "Known source results and complete re-derivations", "placement_basis": "inventory kind and plan condition 2", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Cited/re-derived", "source_statement": "\begin{proposition}[Credited re-derivation: comparison with Calabi--Eckmann deformations]\label{maps:src:D.3.4}

