{"row_key": "S6_04_MAPS_MANIFOLDS:E.1.1", "source_compendium_paper": "III", "source_compendium_label": "maps:src:E.1.1", "source_file": "sections/fourfolds.tex: E.1.1", "source_line": 19636, "source_section": "The fourfold and transverse fibre products", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Counterexample", "source_statement": "\begin{proposition}[Counterexample: the proposed normalization]\label{maps:src:E.1.1}

