{"row_key": "S6_05_ARITHMETIC:C.1.2", "source_compendium_paper": "I", "source_compendium_label": "ari:C.1.2", "source_file": "C_special.tex C.1.2", "source_line": 5314, "source_section": "Special values, local expansions and torsion", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[the phases and the two periods]\label{ari:C.1.2}
With the branch continued from the specified cusp, the exact values are
\begin{align*}
 \frac{\vartheta _1((2-\rho)/3,\rho)}{\eta(\rho)}
   &=e^{\pi i/12}\,3^{1/4}e^{\pi/(6\sqrt3)},\\
 \frac{\vartheta _1((1-i)/2,i)}{\eta(i)}
   &=\sqrt2\,e^{\pi/4},\\
 \beta^{\rm part}(z_1)
   &=-\frac12+i\left(\frac1{\sqrt3}-\frac3{2\pi}\log48\right),\\
 \beta^{\rm part}(z_2)
   &=i\left(\frac32-\frac3\pi\log6\right).
\end{align*}
Consequently $N(z_1)=3^{1/4}$, $N(z_2)=\sqrt2$,
$D_{\rm part}(z_1)=-3\log48/(2\pi)$, and
$D_{\rm part}(z_2)=-3\log6/\pi$.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "citation_key": "AC2026", "original_source": "sources/original/AC26_original_manuscript.pdf", "source_sha256": "283bba102dd1d5dc346af81b28145bdaaea6654398d5032e76e97bafb9a858f2", "actual_reading_scope": "Attached original PDF: Remark 1.3 p.5; Proposition 7.27 pp.62–63; Theorem 9.1 pp.64–65; Proposition 9.11 pp.70–71; Lemma 9.12 pp.71–74; Proposition 9.13 pp.74–75; Remark 9.21 p.81; Theorem 10.5 pp.88–89; Proposition 10.8 pp.92–94. Also original PDF Theorem 5.4(iii) p.32 and its flat-character proof p.35; Theorem 9.1(vi) p.65; Proposition 9.20 p.80; Corollary 9.22 p.81; Remark9.27 p.83. The original PDF, not the transcription, governs the comparison.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.1.2|AC26", "terms_searched": ["Green", "isogen", "norm", "theta", "48", "216", "special value"], "hit_counts": {"Green": 0, "isogen": 1, "norm": 94, "theta": 1, "48": 4, "216": 0, "special value": 0}}, "full_statement_found": false, "kind": "bounded_negative", "locator": "", "relation": "The precise result was not found in the explicitly listed original-source sections and statement searches. This is not a claim of absence from unread sections or from the literature as a whole."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "citation_key": "Engel2026", "original_source": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "source_sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "actual_reading_scope": "S6.tex §1 lines235–280; §2 lines288–390; main-thm lines882–910; integral homology lines1617–1643; remarks1647–1725.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.1.2|E26", "terms_searched": ["Green", "isogen", "norm", "theta", "48", "216", "special value"], "hit_counts": {"Green": 1, "isoge