{"row_key": "S6_05_ARITHMETIC:C.3.1", "source_compendium_paper": "I", "source_compendium_label": "ari:C.3.1", "source_file": "C_special.tex C.3.1", "source_line": 5535, "source_section": "Special values, local expansions and torsion", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[fourth order at the maximum]\label{ari:C.3.1}
On either root branch at $\tau=i$, let
$h=\mu-(1-\tau)/2$ and $\delta=\tau-i$. Then
\begin{align*}
 \tau&=i-\frac{3\pi i}{2}h^2-\frac{9\pi^2i}{8}h^4+O(h^6),\\
 h^2&=\frac{2i}{3\pi}\delta+\frac1{3\pi}\delta^2+O(\delta^3),\\
 \mu&=\frac{1-\tau}{2}
  \mathbin{\pm}\left(\frac{2i\delta}{3\pi}\right)^{1/2}
          \left(1-\frac{i}{4}\delta+O(\delta^2)\right).
\end{align*}
The square root is taken holomorphically on the chosen root chart.
Furthermore
\begin{align}\label{ari:eq:cs-Li}
 \log N={}&\tfrac12\log2-\frac\pi2|h|^2
   +\frac{3\pi^2}{8}|h|^4
   -\frac{3\pi^2}{4}|h|^2\operatorname{Re}(h^2)
   -\frac{5G}{192}\operatorname{Re}(h^4)+O(|h|^6),\\
 D_{\rm part}={}&D_* -\frac2\pi|\delta|
  +\frac1\pi\bigl(|\delta|^2+|\delta|\operatorname{Im}\delta\bigr)
  +\frac{5G}{72\pi^3}\operatorname{Re}(\delta^2)
  +O(|\delta|^3).\nonumber
\end{align}
In particular the leading terms agree with the boundary expansion in Lemma~\ref{push:src:D.2.1}.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "citation_key": "AC2026", "original_source": "sources/original/AC26_original_manuscript.pdf", "source_sha256": "283bba102dd1d5dc346af81b28145bdaaea6654398d5032e76e97bafb9a858f2", "actual_reading_scope": "Attached original PDF: Remark 1.3 p.5; Proposition 7.27 pp.62–63; Theorem 9.1 pp.64–65; Proposition 9.11 pp.70–71; Lemma 9.12 pp.71–74; Proposition 9.13 pp.74–75; Remark 9.21 p.81; Theorem 10.5 pp.88–89; Proposition 10.8 pp.92–94. Also original PDF Theorem 5.4(iii) p.32 and its flat-character proof p.35; Theorem 9.1(vi) p.65; Proposition 9.20 p.80; Corollary 9.22 p.81; Remark9.27 p.83. The original PDF, not the transcription, governs the comparison.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.3.1|AC26", "terms_searched": ["expansion", "equianharmonic", "lemniscatic", "maximum", "minimum"], "hit_counts": {"expansion": 2, "equianharmonic": 0, "lemniscatic": 0, "maximum": 4, "minimum": 0}}, "full_statement_found": false, "kind": "bounded_negative", "locator": "", "relation": "The precise result was not found in the explicitly listed original-source sections and statement searches. This is not a claim of absence from unread sections or from the literature as a whole."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "citation_key": "Engel2026", "original_source": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "source_sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "actual_reading_scope": "S6.tex §1 lines235–280; §2 lines288–390; main-thm lines882–910; integral homology lines1617–1643; remarks1647–1725.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.3.1|E26", "terms_searched": ["expansion", "equianharmonic", "lemniscatic", "maximum", "minimum"], "hit_counts": {"expansion": 0, "eq