{"row_key": "S6_05_ARITHMETIC:C.3.2", "source_compendium_paper": "I", "source_compendium_label": "ari:C.3.2", "source_file": "C_special.tex C.3.2", "source_line": 5624, "source_section": "Special values, local expansions and torsion", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[the equianharmonic point is neither an extremum]\label{ari:C.3.2}
Set $T_0=\sqrt3/2$, $\mu_0=(2-\rho)/3$, and
$p=\wp'_\rho(\mu_0)$. Then $p\ne0$, $p^2=-g_3(\rho)$, and, for
$\delta=\tau-\rho$ on the order-three root chart,
\begin{align*}
 \mu&=\frac{2-\tau}{3}
      +\frac{3p}{16\pi^2}\delta^2
      +\frac{3ip}{32\pi^2T_0}\delta^3+O(\delta^4),\\
 t&=\frac{ip^2}{\pi^3}\delta^3
        \left(1+\frac{3i}{2T_0}\delta+O(\delta^2)\right),\\
 \log N&=\tfrac14\log3+\frac7{192}\operatorname{Re}t
       -\frac{9\pi}{512T_0|p|^{2/3}}|t|^{4/3}
       +O(|t|^{5/3}).
\end{align*}
Thus
\[
 D_{\rm part}(t)=-\frac3{2\pi}\log48
       +\frac7{32\pi}\operatorname{Re}t
       -\frac{27}{256T_0|p|^{2/3}}|t|^{4/3}
       +O(|t|^{5/3}).
\]
The point $t=0$ is neither a local maximum nor a local minimum.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "citation_key": "AC2026", "original_source": "sources/original/AC26_original_manuscript.pdf", "source_sha256": "283bba102dd1d5dc346af81b28145bdaaea6654398d5032e76e97bafb9a858f2", "actual_reading_scope": "Attached original PDF: Remark 1.3 p.5; Proposition 7.27 pp.62–63; Theorem 9.1 pp.64–65; Proposition 9.11 pp.70–71; Lemma 9.12 pp.71–74; Proposition 9.13 pp.74–75; Remark 9.21 p.81; Theorem 10.5 pp.88–89; Proposition 10.8 pp.92–94. Also original PDF Theorem 5.4(iii) p.32 and its flat-character proof p.35; Theorem 9.1(vi) p.65; Proposition 9.20 p.80; Corollary 9.22 p.81; Remark9.27 p.83. The original PDF, not the transcription, governs the comparison.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.3.2|AC26", "terms_searched": ["expansion", "equianharmonic", "lemniscatic", "maximum", "minimum"], "hit_counts": {"expansion": 2, "equianharmonic": 0, "lemniscatic": 0, "maximum": 4, "minimum": 0}}, "full_statement_found": false, "kind": "bounded_negative", "locator": "", "relation": "The precise result was not found in the explicitly listed original-source sections and statement searches. This is not a claim of absence from unread sections or from the literature as a whole."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "citation_key": "Engel2026", "original_source": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "source_sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "actual_reading_scope": "S6.tex §1 lines235–280; §2 lines288–390; main-thm lines882–910; integral homology lines1617–1643; remarks1647–1725.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.3.2|E26", "terms_searched": ["expansion", "equianharmonic", "lemniscatic", "maximum", "minimum"], "hit_counts": {"expansion": 0, "eq