{"row_key": "S6_05_ARITHMETIC:C.4.2", "source_compendium_paper": "I", "source_compendium_label": "ari:C.4.2", "source_file": "C_special.tex C.4.2", "source_line": 5749, "source_section": "Special values, local expansions and torsion", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[the full division identity]\label{ari:C.4.2}
Let $\psi_m$ be the standard division polynomial of a smooth
Weierstrass model, normalized by $\psi_1=1$, $\psi_2=2y$.
For $m\ge2$ and $Q,mQ\ne O$,
\begin{equation}\label{ari:eq:cs-division}
 N(Q)^{m^2}
       =N(mQ)\frac{|\Delta_E|^{(m^2-1)/12}}{|\psi_m(Q)|}.
\end{equation}
For the displayed family this specializes to
\[
 N(P)^4=3^{3/4}|t-1|^{-1/4}N(2P),\qquad
 N(P)^9=16|t|^{-2/3}N(3P).
\]
If $P_t$ has exact order $n$ and $m\ge2$ satisfies
$m\equiv1$ or $-1\pmod n$, then
\begin{equation}\label{ari:eq:cs-torsionvalue}
 N(P_t)^{12}
       =\frac{|\Delta(t)|}{|\psi_m(P_t)|^{12/(m^2-1)}}.
\end{equation}
The positive value on the right is independent of $m$.
