{"row_key": "S6_05_ARITHMETIC:C.6.R3", "source_compendium_paper": "I", "source_compendium_label": "ari:C.6.R3", "source_file": "sections/C_rank.tex C.6.R3", "source_line": 6681, "source_section": "Global heights and the eleven rational CM fibres", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[ARI \ref{ari:C.6.R3}; Proved: the consequences of Gross--Zagier and Kolyvagin]\label{ari:C.6.R3}
For each of the nine rank-one curves there is a positive rational
number $q_i$ such that
\begin{equation}\label{ari:eq:Cr-rational-factor}
 \frac{L'(E_i,1)}{\Omega_i}=q_i\widehat h(P_i).
\end{equation}
Their Tate--Shafarevich groups over $\Q$ are finite. Consequently
the corresponding $D_{\rm part}$ is an explicit logarithm minus
$(6/(\pi q_i))L'(E_i,1)/\Omega_i$. The two rank-two curves do
not satisfy a rank-one formula; there $L'(E_i,1)=0$ while
$\widehat h(P_i)>0$.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "citation_key": "AC2026", "original_source": "sources/original/AC26_original_manuscript.pdf", "source_sha256": "283bba102dd1d5dc346af81b28145bdaaea6654398d5032e76e97bafb9a858f2", "actual_reading_scope": "Attached original PDF: Remark 1.3 p.5; Proposition 7.27 pp.62–63; Theorem 9.1 pp.64–65; Proposition 9.11 pp.70–71; Lemma 9.12 pp.71–74; Proposition 9.13 pp.74–75; Remark 9.21 p.81; Theorem 10.5 pp.88–89; Proposition 10.8 pp.92–94. Also original PDF Theorem 5.4(iii) p.32 and its flat-character proof p.35; Theorem 9.1(vi) p.65; Proposition 9.20 p.80; Corollary 9.22 p.81; Remark9.27 p.83. The original PDF, not the transcription, governs the comparison.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.6.R3|AC26", "terms_searched": ["height", "rank", "Gross", "Zagier", "Sha", "Tate", "Rubin", "canonical"], "hit_counts": {"height": 13, "rank": 64, "Gross": 0, "Zagier": 0, "Sha": 8, "Tate": 82, "Rubin": 0, "canonical": 11}}, "full_statement_found": false, "kind": "bounded_negative", "locator": "", "relation": "The precise result was not found in the explicitly listed original-source sections and statement searches. This is not a claim of absence from unread sections or from the literature as a whole."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "citation_key": "Engel2026", "original_source": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "source_sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "actual_reading_scope": "S6.tex §1 lines235–280; §2 lines288–390; main-thm lines882–910; integral homology lines1617–1643; remarks1647–1725.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.6.R3|E26", "terms_searched": ["height", "rank", "Gross", "Zagier", "Sha", "Tate", "Rubin", "canonical"], "