{"row_key": "S6_05_ARITHMETIC:C.8.4", "source_compendium_paper": "I", "source_compendium_label": "ari:C.8.4", "source_file": "sections/C_analytic.tex C.8.4", "source_line": 7755, "source_section": "An analytic proof of the elliptic maximum", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[the first three normalized duplication steps]\label{ari:C.8.4}
Put $u=t-1$. For $n=2^k$, $k=1,2,3$, and $nP\ne O$,
\begin{equation}\label{ari:eq:ca-ladder}
 \left(\frac{N(P)}{\sqrt2}\right)^{n^2}
 =\frac{3^{3/4}}{2n}\,
       \frac{N(nP)|u|^{-1/4}}{|A_k(u)|},
\end{equation}
where
\begin{align*}
 A_1(u)&=1,\qquad A_2(u)=1-5u/27,\\
 A_3(u)&=1-\frac{217}{27}u-\frac{20486}{729}u^2
       +\frac{10910}{19683}u^3
       +\frac{161383}{177147}u^4
       -\frac{245}{14348907}u^5.
\end{align*}
On $|u|\le1/28$ we have $|A_3(u)|\ge1-10|u|$.
For every $k\ge1$, not just these first three steps, define
\[
 E_k(t)=\frac{|\Delta_E|^{(4^k-1)/12}|t-1|^{1/4}}
 {2^{4^k/2}|\psi_{2^k}(P)|}.
\]
Then $(N(P)/\sqrt2)^{4^k}=E_k(t)N(2^kP)|t-1|^{-1/4}$,
and the removable limiting value is
\[
 \lim_{t\to1}E_k(t)=\frac{3^{3/4}}{2^{k+1}}
                 =2^{1-k}\frac{3^{3/4}}4.
\]
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "not_found_in_checked_scope", "citation_key": "AC2026", "original_source": "sources/original/AC26_original_manuscript.pdf", "source_sha256": "283bba102dd1d5dc346af81b28145bdaaea6654398d5032e76e97bafb9a858f2", "actual_reading_scope": "Attached original PDF: Remark 1.3 p.5; Proposition 7.27 pp.62–63; Theorem 9.1 pp.64–65; Proposition 9.11 pp.70–71; Lemma 9.12 pp.71–74; Proposition 9.13 pp.74–75; Remark 9.21 p.81; Theorem 10.5 pp.88–89; Proposition 10.8 pp.92–94. Also original PDF Theorem 5.4(iii) p.32 and its flat-character proof p.35; Theorem 9.1(vi) p.65; Proposition 9.20 p.80; Corollary 9.22 p.81; Remark9.27 p.83. The original PDF, not the transcription, governs the comparison.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.8.4|AC26", "terms_searched": ["maximum", "critical", "Mahler", "Gaussian", "equidistribution", "duplication", "ray", "216"], "hit_counts": {"maximum": 4, "critical": 3, "Mahler": 0, "Gaussian": 0, "equidistribution": 0, "duplication": 0, "ray": 29, "216": 0}}, "full_statement_found": false, "kind": "bounded_negative", "locator": "", "relation": "The precise result was not found in the explicitly listed original-source sections and statement searches. This is not a claim of absence from unread sections or from the literature as a whole."}", "found_in_E26": "{"status": "not_found_in_checked_scope", "citation_key": "Engel2026", "original_source": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "source_sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "actual_reading_scope": "S6.tex §1 lines235–280; §2 lines288–390; main-thm lines882–910; integral homology lines1617–1643; remarks1647–1725.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "S6_05_ARITHMETIC:C.8.4|E26", "terms_searched": ["maximum", "critical", "Mahler", "Gaussia