{"row_key": "working_edition:thm:sphere-recognition", "source_compendium_paper": "I", "source_compendium_label": "mapsI:top:thm:sphere-recognition", "source_file": "sources/workbench/topology_reduction.tex", "source_line": 30617, "source_section": "The alternate collapse and Mayer--Vietoris route", "placement_basis": "plan §3 identifies construction/topology appendix re-derivations", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Theorem", "source_statement": "\begin{theorem}[sphere recognition from the exact inputs]
