{"row_key": "working_edition:cusp-cone-S24-route", "source_compendium_paper": "III", "source_compendium_label": "wb:cusp-cone-S24-route", "source_file": "sources/workbench/cusp_cone_sphere_routes.tex", "source_line": 36733, "source_section": "Local covers, global quotients and cusp carriers", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Theorem", "source_statement": "\begin{theorem}[Exact cone-compactified \(S^{24}\) route]
\label{wb:cusp-cone-S24-route}
There is a continuous surjective based quotient map
\begin{equation}
 q_1:(X,x_0)\longrightarrow(\mathcal C,c_0),\qquad x_0\in W,
 \label{wb:cusp-cone-q1}
\end{equation}
defined as follows:
\begin{enumerate}
\item over \(P\), it is
\((f,\theta_\gamma):f^{-1}(P)\to P\times S^1\), equivalently the
restriction of \(\chi_\gamma\) to \(f^{-1}(P)\);
\item over \(D_j\), \(j=1,2\), it is the finite-filling map
\(N_j\to C_j\) from \cref{wb:cusp-spec-finite-Seifert-target};
\item on \(N_0\setminus W\), writing \(t=re^{i\phi}\), it is
\begin{equation}
 x\longmapsto[r,(e^{i\phi},\theta_\gamma(x))]
 \in\operatorname{Cone}(\partial D_0\times S^1),
 \label{wb:cusp-cone-q1-cusp-formula}
\end{equation}
and every point of \(W\) maps to \(c_0\).
\end{enumerate}
The fourth smash power is a global based map
\begin{equation}
 q_1^{\wedge4}:X^{\wedge4}\longrightarrow\mathcal C^{\wedge4}.
 \label{wb:cusp-cone-S24-map}
\end{equation}
Using \(X\cong_{\mathrm{diff}}S^6\), its source is
\begin{equation}
 X^{\wedge4}\cong(S^6)^{\wedge4}\cong S^{24}.
 \label{wb:cusp-cone-S24-source}
\end{equation}
On four synchronized radial fibres, the canonical product-to-smash quotient
maps restrict to embeddings on the source fibre product and the interior
target-product cross-section.  Under those embeddings,
\cref{wb:cusp-cone-S24-map} restricts exactly to
\begin{equation}
 \chi_{\gamma,T}^{\times4}:F_T^4\longrightarrow C_T^4,\qquad
 C_T=\mathbb R/\ell_T\mathbb Z.
 \label{wb:cusp-cone-S24-fibre-map}
\end{equation}
With its Euclidean \(\ell^2\)-product flat quotient metric,
\begin{equation}
 \operatorname{sys}(C_T^4)=\ell_T
 =T+H-B+O(T^{-1}),\qquad
 (C_T^4,0)\longrightarrow(\mathbb R^4,0)
 \label{wb:cusp-cone-S24-R4-limit}
\end{equation}
in pointed local-isometric, pointed smooth, and pointed
Gromov--Hausdorff topology.

The target homology is
\begin{equation}
 \widetilde H_k(\mathcal C;\mathbb Z)\cong
 \begin{cases}
  \mathbb Z,&k=2,3,\\
  0,&\text{otherwise},
 \end{cases}
 \label{wb:cusp-cone-C-homology}
\end{equation}
and
\begin{equation}
 \widetilde H_k(\mathcal C^{\wedge4};\mathbb Z)\cong
 \begin{cases}
  \mathbb Z,&k=8,12,\\
  \mathbb Z^4,&k=9,11,\\
  \mathbb Z^6,&k=10,\\
  0,&\text{otherwise}.
 \end{cases}
 \label{wb:cusp-cone-C-smash-homology}
\end{equation}
\end{theorem}", "historical_literature_checks": {"found_in_AC26": "{"status": "known_construction_input_found", "full_statement_found": false, "locator": "Original Lemmas4.2–4.3, Theorem4.5, Propositions4.6–4.7 and Corollary4.8 p30; sphere recognition Theorem8.1. Prior exact full-read scopes retained.", "relation": "Known underlying marked complex torus/sphere family and cusp/finite-fillings data only. The finite Seifert pieces originate in the existing torus construction and Engel’s circle-quotient idea. The coned target, its actual glued map and integral relative homology are the receiving construction; no literal global flat extension is asserted.", "terms_searched": ["S.?24", "smash", "suspension", "Seifert"], "search_record": "deliverables/work/cdp_audit/carrier_credit/searches_164.json#cusp-cone-S24-route|AC26", "searched_file": "sources/external/root/AC26_pdf_text.txt", "searched_sha256": "e3a403c0ef610e2aefb22f56b59dd495931dc7015b045cdc30f1403a31a65040", "hit_count": 4, "context_record": "deliverables/work/cdp_audit/carrier_credit/context_readings.json#AC26"}", "found_in_E26": "{"status": "known_construction_input_found", "full_statement_found": false, "locator": "Original torus/sphere construction; Lemma3.8 (source842–850) and Remark8.3 (1685–1723) for the invariant-circle antecedent.", "relation": "Known underlying marked complex torus/sphere family and cusp/finite-fillings data only. The finite Seifert pieces originate in the existing torus construction and Engel’s circle-quotient idea. The coned target, its actual glued map and integral relative homology are the receiving construction; no literal global flat extension is asserted.", "terms_searched": ["S.?24", "smash", "suspension", "Seifert"], "search_record": "deliverables/work/cdp_audit/carrier_credit/searches_164.json#cusp-cone-S24-route|E26", "searched_file": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "searched_sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "hi