{"row_key": "WORKING_INV:prop:absolute-cotangent-direct-images", "source_compendium_paper": "I", "source_compendium_label": "inv:A1.3", "source_file": "workbench/hodge_frolicher.tex", "source_line": 2737, "source_section": "The cotangent direct images and the decisive period scalar", "placement_basis": "candidate body placement; source-credit and proof reviews pending", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Proposition", "source_statement": "\begin{proposition}[All absolute cotangent direct images]\label{inv:A1.3}\label{wb:prop:absolute-cotangent-direct-images}
For every admissible $c$, the six direct images are
\begin{equation}\label{inv:eq:A-absolute-table}
\begin{array}{c|cc}
q&R^qf_*\Omega_X^1&R^qf_*\Omega_X^2\\\hline
0&\OO(-2)&\OO(-2)\oplus\OO(-1)\\
1&\OO\oplus\OO(-1)^2&\OO(-2)\oplus\OO(-1)^2\\
2&\OO\oplus\OO(-1)&\OO.
\end{array}
\end{equation}
In particular every listed sheaf is torsion-free.
\end{proposition}", "historical_literature_checks": {"found_in_AC26": "{"status": "found", "citation_key": "AC2026", "original_source": "sources/original/AC26_original_manuscript.pdf", "source_sha256": "283bba102dd1d5dc346af81b28145bdaaea6654398d5032e76e97bafb9a858f2", "actual_reading_scope": "Attached original PDF: Remark 1.3 p.5; Proposition 7.27 pp.62–63; Theorem 9.1 pp.64–65; Proposition 9.11 pp.70–71; Lemma 9.12 pp.71–74; Proposition 9.13 pp.74–75; Remark 9.21 p.81; Theorem 10.5 pp.88–89; Proposition 10.8 pp.92–94. Also original PDF Theorem 5.4(iii) p.32 and its flat-character proof p.35; Theorem 9.1(vi) p.65; Proposition 9.20 p.80; Corollary 9.22 p.81; Remark9.27 p.83. The original PDF, not the transcription, governs the comparison.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "WORKING_INV:prop:absolute-cotangent-direct-images|AC26", "terms_searched": ["direct image", "structure", "cup", "gamma", "logarithmic", "cotangent"], "hit_counts": {"direct image": 5, "structure": 39, "cup": 15, "gamma": 0, "logarithmic": 12, "cotangent": 0}}, "locator": "Remark1.3 p.5 and Remark9.21 p.81", "relation": "The cotangent/direct-image calculation and h12=1 are explicitly uncomputed/expected in AC26. This is an earlier open target, not an earlier proof.", "full_statement_found": false, "kind": "earlier_open_problem"}", "found_in_E26": "{"status": "not_found_in_checked_scope", "citation_key": "Engel2026", "original_source": "sources/papers/arXiv_2609.38442_Engel_src/S6.tex", "source_sha256": "95ea78327c33351d609a3001539756f0043dfdef13a37a81927608c953c98c36", "actual_reading_scope": "S6.tex §1 lines235–280; §2 lines288–390; main-thm lines882–910; integral homology lines1617–1643; remarks1647–1725.", "search": {"record_file": "work/invariants_arithmetic/credit_search_log.json", "record_key": "WORKING_INV:prop:absolute-cotangent-direct-images|E26", "terms_searched": ["direct image", "structure", "cup", "gamma", "logarithmic", "cot