{"row_key": "WORKING_EDITION_COURSE_PROVIDER:CG-S6-CHAIN-COROLLARY-2.2", "source_compendium_paper": "I", "source_compendium_label": "mapsI:chain:corollary:2.2", "source_file": "sources/codex_workspace/courses/CG-S6/src/thom-euler-for-lesson11.md:69", "source_line": 30824, "source_section": "Elementary integral chain constructions", "placement_basis": "plan §3 classical/course material", "placement_state": "provisional editorial mapping; no current mathematical validation inferred", "source_kind": "Classical rederivation", "source_statement": "\begin{corollary}[excision]
